class BaseClassifier(BaseModel):
    def __init__(self, model: nn.Module, num_classes: int, **kwargs: Any) -> None:
        super().__init__(**kwargs)
        self.model = model
        self.num_classes = num_classes

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """The forward method of the BaseClassifier."""
        return self.model(x)

    def _loss(self, output: torch.Tensor, target: torch.Tensor) -> torch.Tensor:
        """The loss method of the BaseClassifier."""
        return F.cross_entropy(output, target)

    def _get_metrics(self, output: torch.Tensor, target: torch.Tensor) -> Dict[str, Any]:
        """The metrics method of the BaseClassifier."""
        return {"accuracy": torch.mean((output.argmax(dim=1) == target).float())}

    def _get_optimizer(self) -> torch.optim.Optimizer:
        """The optimizer method of the BaseClassifier."""
        return torch.optim.Adam(self.model.parameters(), lr=self.lr)

    def _get_scheduler(self) -> Optional[torch.optim.lr_scheduler._LRScheduler]:
        """The scheduler method of the BaseClassifier."""
        return torch.optim.lr_scheduler.StepLR(self.optimizer, step_size=10, gamma=0.1)

    def _get_device(self) -> torch.device:
        """The device method of the BaseClassifier."""
        return _get_model_device(self.model)

